Method.Implementation:
/// #### 		Is the menu button  not appearing?			####
/// ####  Have you added "d ##super()" to your onPrepage()? ####

s ..ToolBar = ..basicToolbar

s st = ..basicToolbar.GetButtonById("btnMenu", .btnMenu)
s str = "<div class='k-button' onclick='SendJSON(HomePagebtn"_..basicToolbar.ControlID_")'><span class='fal fa-home'></span></div>"

s str1 = "var HomePagebtn"_..basicToolbar.ControlID_" = "_..basicToolbar.RaiseEventCallBack("GoToHomepage", "onClickEvent").ToJSON()_";"
			
s btnMenu.template = str
s strm = ##class(%GlobalBinaryStream).%New()
d strm.Write(str1)
s btnMenu.templateStream = strm


s st = ..basicToolbar.GetButtonById("tbHeader", .btnHeader)
s btnHeader.text = ..Title


i (..Environment.Security.AuthorizedToUseDevMode()) 
{	

	s st = ..basicToolbar.GetButtonById("btnDev", .devMode)
	s devMode.onToggle = "DevModePressed"
	
	i (..Environment.DevMode)	
	{
		s devMode.selected = 1
	} else {
		s devMode.selected = 0	
	}
	s devMode.togglable = "true"
	
} else {
	
	;s st = ..basicToolbar.RemoveButton("btnDev")
	s ..btnDev.Visible=0
	s ..btnTracker.Visible=0
	
}

if (..Environment.Client.isMobile())
{
	s ..btnDev.overflow = "always"
	s ..btnMenu.overflow = "never"
}

i '..IsDevTeam() s ..btnRfrsh.Visible = 2
	
// עזרה מרחוק - כפתור צף בכל מסך שיורש מ-commonXTafPage
d ##class(TafnitCore.System.UI.App.commonXTafPage).AddRemoteHelpButton(##this)
	
q 1
